// Chuyển ảnh CCCD sang base64 + dựng body gọi Gemini
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const bin = $input.item.binary && $input.item.binary.data ? $input.item.binary.data : {};
const mimeType = bin.mimeType || 'image/jpeg';
const trigger = $('Drive: ảnh CCCD mới').item.json;
const prompt = "Bạn là trợ lý nhập liệu. Ảnh là CĂN CƯỚC CÔNG DÂN (CCCD) Việt Nam — có thể là mặt trước, mặt sau, hoặc cả hai. Đọc thật kỹ và trích xuất TẤT CẢ thông tin.\n\nCHỈ TRẢ VỀ 1 object JSON đúng cấu trúc (không giải thích):\n{\n  \"so_cccd\": \"số CCCD (12 chữ số) hoặc số CMND nếu là bản cũ\",\n  \"ho_ten\": \"họ và tên đầy đủ, VIẾT HOA như trên thẻ\",\n  \"ngay_sinh\": \"ngày sinh dạng DD/MM/YYYY\",\n  \"gioi_tinh\": \"Nam hoặc Nữ\",\n  \"quoc_tich\": \"quốc tịch\",\n  \"que_quan\": \"quê quán đầy đủ\",\n  \"noi_thuong_tru\": \"nơi thường trú / nơi cư trú đầy đủ\",\n  \"co_gia_tri_den\": \"ngày hết hạn (Có giá trị đến), DD/MM/YYYY hoặc chữ nếu ghi khác\",\n  \"ngay_cap\": \"ngày cấp (mặt sau), DD/MM/YYYY\",\n  \"noi_cap\": \"nơi cấp (vd: Cục Cảnh sát QLHC về TTXH)\",\n  \"dac_diem_nhan_dang\": \"đặc điểm nhận dạng nếu có (mặt sau)\",\n  \"do_tin_cay\": \"cao | trung bình | thấp — mức chắc chắn khi đọc\",\n  \"can_kiem_tra\": true hoặc false — true nếu có trường quan trọng (số CCCD, họ tên, ngày sinh) không chắc,\n  \"ly_do_kiem_tra\": \"lý do, rỗng nếu không\"\n}\nTrường nào không thấy trên ảnh thì để chuỗi rỗng. Không bịa thông tin.";
return { json: {
  fileId: trigger.id,
  fileName: trigger.name,
  body: {
    contents: [{ parts: [ { text: prompt }, { inline_data: { mime_type: mimeType, data: base64 } } ] }],
    generationConfig: { temperature: 0, response_mime_type: 'application/json' }
  }
} };

// Phân tích JSON Gemini → cột CCCD
const prep = $('Chuẩn bị ảnh (Gemini)').item.json;
const fileId = prep.fileId, fileName = prep.fileName;
let text = '';
try { text = $json.candidates[0].content.parts[0].text; } catch (e) { text = ''; }
let clean = (text || '').trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
let data = {}; let parseError = '';
try { data = JSON.parse(clean); } catch (e) { parseError = 'Không đọc được JSON từ AI'; data = {}; }

const conf = String(data.do_tin_cay || '').toLowerCase();
const lowConf = conf.includes('thấp') || conf.includes('thap') || conf === 'low';
const aiFlag = data.can_kiem_tra === true || data.can_kiem_tra === 'true';
const missing = [];
if (!data.so_cccd) missing.push('số CCCD');
if (!data.ho_ten) missing.push('họ tên');
if (!text) missing.push('OCR trống');
const needsReview = !!(parseError || lowConf || aiFlag || missing.length);
const reasons = [];
if (parseError) reasons.push(parseError);
if (missing.length) reasons.push('Thiếu/khó đọc: ' + missing.join(', '));
if (lowConf) reasons.push('AI báo độ tin cậy thấp');
if (aiFlag && data.ly_do_kiem_tra) reasons.push(data.ly_do_kiem_tra);

return { json: {
  'Thời gian xử lý': new Date().toISOString(),
  'Tên file': fileName || '',
  'Link ảnh': fileId ? ('https://drive.google.com/file/d/' + fileId + '/view') : '',
  'Số CCCD': data.so_cccd || '',
  'Họ và tên': data.ho_ten || '',
  'Ngày sinh': data.ngay_sinh || '',
  'Giới tính': data.gioi_tinh || '',
  'Quốc tịch': data.quoc_tich || '',
  'Quê quán': data.que_quan || '',
  'Nơi thường trú': data.noi_thuong_tru || '',
  'Có giá trị đến': data.co_gia_tri_den || '',
  'Ngày cấp': data.ngay_cap || '',
  'Nơi cấp': data.noi_cap || '',
  'Đặc điểm nhận dạng': data.dac_diem_nhan_dang || '',
  'Độ tin cậy': data.do_tin_cay || '',
  'Cần kiểm tra': needsReview ? 'CÓ' : 'Không',
  'Lý do kiểm tra': reasons.join('; ')
} };
